-- OUMMAH Boycott — scanner réactif + cache produits scannés + extension catalogue.
-- Périmètre strict : module Boycott uniquement.
-- boycott_scanned_products est un cache d'identification/scan ; boycott_entities reste la source canonique du statut rouge.

create table if not exists public.boycott_scanned_products (
  barcode text primary key,
  product_name text,
  brand text,
  image_url text,
  last_result text not null default 'unknown',
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  scan_count bigint not null default 1,
  constraint boycott_scanned_products_barcode_valid check (barcode ~ '^[0-9]{8,14}$'),
  constraint boycott_scanned_products_result_allowed check (last_result in ('boycott','ok','unknown'))
);

alter table public.boycott_scanned_products enable row level security;

drop policy if exists "boycott scanned products public read" on public.boycott_scanned_products;
create policy "boycott scanned products public read"
on public.boycott_scanned_products
for select
to anon, authenticated
using (true);

create or replace function public.record_boycott_scanned_product(
  p_barcode text,
  p_product_name text default null,
  p_brand text default null,
  p_image_url text default null,
  p_last_result text default 'unknown'
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_barcode is null or p_barcode !~ '^[0-9]{8,14}$' then
    return;
  end if;

      p_barcode,
      nullif(btrim(p_product_name), ''),
      nullif(btrim(p_brand), ''),
      nullif(btrim(p_image_url), ''),
      case when p_last_result in ('boycott','ok','unknown') then p_last_result else 'unknown' end,
      now(),
      now(),
      1
    )
  on conflict (barcode) do update set
    product_name = coalesce(excluded.product_name, boycott_scanned_products.product_name),
    brand = coalesce(excluded.brand, boycott_scanned_products.brand),
    image_url = coalesce(excluded.image_url, boycott_scanned_products.image_url),
    last_result = excluded.last_result,
    last_seen_at = now(),
    scan_count = boycott_scanned_products.scan_count + 1;
end;
$$;

revoke all on function public.record_boycott_scanned_product(text,text,text,text,text) from public;
grant execute on function public.record_boycott_scanned_product(text,text,text,text,text) to anon, authenticated;

on conflict (slug) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  parent_group = excluded.parent_group,
  summary = excluded.summary,
  evidence_kind = excluded.evidence_kind,
  sources = excluded.sources,
  last_verified_at = excluded.last_verified_at,
  is_active = excluded.is_active,
  updated_at = now();
